SELECT *, AVG(monthly_fee) OVER (PARTITION BY status ORDER BY start_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS monthly_fee_avg_2, LAST_VALUE(monthly_fee, TRUE) OVER (PARTITION BY plan ORDER BY end_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_monthly_fee, SUM(monthly_fee) OVER w_hist AS cumulative_monthly_fee FROM subscriptions WINDOW w_hist AS (PARTITION BY customer_id, status ORDER BY monthly_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
